/* cppi::8c615cd233049ca0b38412bca90cd14c8ad383d612839f8bbd5293139a995ac5 */
select trade_date, business_date, changed_date, abor_transaction_number, cost_or_tax_present, transaction_cancellation_flag
from (
    SELECT *,
           ROW_NUMBER() OVER (
               PARTITION BY scd_transaction_number_primary_key
						order by
							changed_date desc -- change date is actual loaded date so use this to get the latest data.
           ) AS rn
    FROM trades_deals.scd_transactions
    WHERE accounting_framework_id = 'PCLFWKMAIN'
)
where abor_transaction_number = 20250613015521

